  "alien isolation": {
    "id": "mc-alien-isolation",
    "source": "metacritic",
    "score": 79,
    "tier": "Strong",
    "numReviews": 50,
    "url": "https://www.metacritic.com/game/alien-isolation/critic-reviews/",
    "summary": "Alien: Isolation is a first-person survival horror game which captures the fear and tension evoked by Ridley Scott’s 1979 classic film. Players find themselves in an atmosphere of constant dread and mortal danger as an unpredictable, ruthless Xenomorph is stalking and killing deep in the shadows. Underpowered and underprepared, you must scavenge resources, improvise solutions and use your wits, not just to succeed in your mission, but to simply stay alive.",
    "isVerified": true,
    "isSynthetic": false
  },
